const d = $input.first().json;
const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const fecha = (f) => new Intl.DateTimeFormat('es-MX', { day: 'numeric', month: 'short', year: 'numeric', timeZone: 'UTC' }).format(new Date(f + 'T12:00:00Z'));
const cuando = (a) => a.tipo_aviso === 'vencida' ? `vencida hace ${-a.dias} día(s)` : a.tipo_aviso === 'sin_factura' ? 'cumplida, falta factura' : a.dias === 0 ? 'vence hoy' : `vence en ${a.dias} día(s)`;
const grupo = (titulo, lista) => lista.length ? `<h3>${titulo} (${lista.length})</h3><ul>` + lista.map((a) => `<li><a href="${esc(a.url)}">${esc(a.titulo)}</a> · ${esc(a.ambito)} · ${fecha(a.vence)} · <strong>${cuando(a)}</strong>${a.detalle ? ` · ${esc(a.detalle)}` : ''}</li>`).join('') + '</ul>' : '';
const html = `<p>Resumen del calendario de cumplimiento del ${fecha(d.hoy)}.</p>` + grupo('Vencidas', d.avisos.vencida) + grupo('Por vencer', d.avisos.por_vencer) + grupo('Cumplidas sin factura', d.avisos.sin_factura);
const claves = [...d.avisos.vencida, ...d.avisos.por_vencer, ...d.avisos.sin_factura].map((a) => a.clave);
return [{ json: { para: d.destinatarios.join(','), asunto: `Cumplimiento: ${d.avisos.vencida.length} vencidas, ${d.avisos.por_vencer.length} por vencer`, html, claves } }];

const d = $input.first().json;
const LIMITE = 3800;
const linea = (a) => `• <${a.url}|${a.titulo}> · ${a.ambito ?? ''} · ${a.tipo_aviso === 'vencida' ? `vencida hace ${-a.dias} día(s)` : a.tipo_aviso === 'sin_factura' ? 'falta factura' : a.dias === 0 ? 'vence hoy' : `vence en ${a.dias} día(s)`}`;
const grupos = [['Vencidas', d.avisos.vencida], ['Por vencer', d.avisos.por_vencer], ['Cumplidas sin factura', d.avisos.sin_factura]];
let text = `*Cumplimiento ${d.hoy}*`;
const claves = [];
let omitidos = 0;
for (const [titulo, lista] of grupos) {
  if (!lista.length) continue;
  let bloque = `\n\n*${titulo} (${lista.length})*`;
  let incluidos = 0;
  for (const a of lista.slice(0, 15)) {
    const ln = '\n' + linea(a);
    if (text.length + bloque.length + ln.length > LIMITE - 60) break;
    bloque += ln;
    claves.push(a.clave);
    incluidos++;
  }
  omitidos += lista.length - incluidos;
  if (incluidos > 0) text += bloque;
}
if (omitidos > 0) text += `\n\n… y ${omitidos} más en el portal`;
return [{ json: { text, claves } }];
